const http = require('http');

const server = http.createServer((req, res) => {
  // We check BOTH the URL and the METHOD to determine the action

  if (req.url === '/users') {
    if (req.method === 'GET') {
      res.end("Reading all users");
    }
    else if (req.method === 'POST') {
      res.end("Creating a new user");
    }
    else if (req.method === 'DELETE') {
      // Dangerous! Deleting the entire collection.
      res.end("Deleting all users");
    }
    else {
      res.writeHead(405); // Method Not Allowed
      res.end(`Cannot ${req.method} /users`);
    }
  }
});

console.log("In modern Express apps, this routing is simplified to app.get(), app.post(), etc.");
